// statusStyles and indent each line under its 2-space gutter.
func emitStaleHooksWarning(w io.Writer, drifts []agent.DriftReport) {
	for _, line := range staleHooksWarningLines(newStatusStyles(w), drifts) {
		fmt.Fprintln(w, line)
	}
}

